from decimal import Decimal, InvalidOperation


def _value(row: dict | None, column: str) -> str:
    if row is None:
        return ""
    value = row.get(column, "")
    return "" if value is None else value


def _number(value: object) -> Decimal:
    if value == "" or value is None:
        return Decimal(0)
    try:
        return Decimal(str(value))
    except (InvalidOperation, ValueError):
        return Decimal(0)


def _lookup(
    tables: dict | None,
    table_name: str,
    key_col: str,
    key_val: object,
    out_col: str,
) -> str:
    if tables is None:
        return ""

    rows = tables.get(table_name, [])
    for row in rows:
        if _value(row, "DEL_FLG") == "Y":
            continue
        if _value(row, key_col) == key_val:
            return _value(row, out_col)
    return ""


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    tables: dict | None = None,
    table: str = "ORD_HEADER",
) -> list[dict]:
    errors: list[dict] = []

    def add(code: str, message: str) -> None:
        errors.append(
            {
                "code": code,
                "message": message,
                "severity": "BLOCK",
            }
        )

    if table == "ORD_HEADER":
        disc_pct = _number(_value(record, "DISC_PCT"))

        # ORD-001
        if event in ("INSERT", "UPDATE"):
            if not (disc_pct >= 0 and disc_pct <= 100):
                add("E5001", "Discount out of range")

        # ORD-002
        if event == "UPDATE":
            owner_role = _lookup(
                tables,
                "USR_MASTER",
                "USR_ID",
                _value(record, "OWNER_UID"),
                "ROLE_ID",
            )
            if disc_pct > 20 and owner_role != "MGR" and owner_role != "ADMIN":
                add(
                    "E5002",
                    "Discount over 20 percent requires manager role",
                )

        # ORD-003
        if event == "UPDATE":
            old_status = _value(old, "STAT_CD")
            status = _value(record, "STAT_CD")
            if old_status == "I" and status != "I" and status != "X":
                add("E5003", "Invoiced order can only be cancelled")

    elif table == "ORD_LINE":
        # ORD-004
        if event in ("INSERT", "UPDATE"):
            if not (_number(_value(record, "QTY")) > 0):
                add("E5004", "Quantity must be positive")

        # ORD-005
        if event == "INSERT":
            active_flag = _lookup(
                tables,
                "PROD_MASTER",
                "PROD_ID",
                _value(record, "PROD_ID"),
                "ACTIVE_FLG",
            )
            if active_flag != "Y":
                add("E5005", "Product not active")

    return errors


def is_blocked(errors: list[dict]) -> bool:
    return any(error.get("severity") == "BLOCK" for error in errors)
